import { expandTable } from '@polymorph/registry/screen-table'

import type { ScreenVocabulary } from './members'
import { TABLE } from './vocabulary.gen'

/**
 * The vocabulary a screen is checked and drawn with at run time: the part of
 * the registry `validateSpec` and the walk read, generated by `pnpm registry`
 * (`packages/registry/src/screen-table.ts`) and expanded once, when this
 * module loads. A renderer hands it to the walk; `checkScreen` and the card
 * read it when they are given no other.
 */
export const VOCABULARY: ScreenVocabulary = /* @__PURE__ */ expandTable(TABLE)

export {
  allowedMembers,
  CODE_HOSTS,
  type ChildrenKind,
  defaultMembers,
  memberNames,
  surfaceOf,
  type MemberOptions,
  type ScreenSurface,
  type ScreenVocabulary,
  type TableMember,
  type TablePart,
  type TablePrimitive,
  type TableProp,
} from './members'
